const userId = $json.from || $json.contact;
const messageText = $json.body || $json.text;
const messageId = $json.id;
const timestamp = Date.now();

if (!$workflow.static.messageBuffers) {
  $workflow.static.messageBuffers = {};
}

if (!$workflow.static.messageBuffers[userId]) {
  $workflow.static.messageBuffers[userId] = {
    messages: [],
    lastProcessed: 0
  };
}

const userBuffer = $workflow.static.messageBuffers[userId];

userBuffer.messages.push({
  id: messageId,
  text: messageText,
  timestamp: timestamp,
  isEdit: $json.editedTimestamp ? true : false
});

userBuffer.messages = userBuffer.messages.filter(msg => 
  timestamp - msg.timestamp < 10000
);

return {
  ...$json,
  bufferedMessages: userBuffer.messages,
  messageCount: userBuffer.messages.length,
  shouldWait: timestamp - userBuffer.lastProcessed < 3000
};

const userId = $json.from || $json.contact;
const currentTime = Date.now();

const userBuffer = $workflow.static.messageBuffers[userId];

if (!userBuffer || userBuffer.messages.length === 0) {
  return $json;
}

const recentMessages = userBuffer.messages.filter(msg => 
  currentTime - msg.timestamp < 8000
);

const combinedText = recentMessages
  .map(msg => msg.text)
  .filter(text => text && text.trim())
  .join(' ');

const hasEdits = recentMessages.some(msg => msg.isEdit);

userBuffer.lastProcessed = currentTime;

return {
  ...$json,
  body: combinedText,
  originalMessage: $json.body,
  hasMultipleMessages: recentMessages.length > 1,
  hasEdits: hasEdits,
  messageCount: recentMessages.length
};
